-- NOVA v9.1.1 / de-fa / B1 / Batch 01 / Chapter 02 / Series 082

-- Continues the passed Series 081 storyline. Atomic staging unit; not publishable alone.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

SET time_zone = '+00:00';

START TRANSACTION;

SET @course_id=(SELECT id FROM courses WHERE course_key='de-fa' LIMIT 1);

SET @level_id=(SELECT id FROM levels WHERE course_id=@course_id AND cefr_level='B1' LIMIT 1);

SET @module_id=(SELECT id FROM modules WHERE level_id=@level_id AND sort_order=1 LIMIT 1);

SET @batch_id=(SELECT id FROM content_batches WHERE level_id=@level_id AND batch_number=1 LIMIT 1);

SET @prior_chapter_id=(SELECT ch.id FROM chapters ch JOIN modules m ON m.id=ch.module_id WHERE m.level_id=@level_id AND ch.series_number=81 AND ch.status='validated' LIMIT 1);

SET @mia_id=(SELECT id FROM characters WHERE course_id=@course_id AND name='Mia' LIMIT 1);

SET @sara_id=(SELECT id FROM characters WHERE course_id=@course_id AND name='Sara' LIMIT 1);

INSERT INTO chapters (module_id,batch_id,chapter_key,series_number,global_sort_order,title,title_translation,description,description_translation,planned_lesson_count,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES (@module_id,@batch_id,'de-fa-b1-c02',82,2,'Warum willst du das machen?','چرا می خوای این کار رو انجام بدی؟','Mia ordnet ihre beruflichen Gründe und übt, ihre Motivation klar und respektvoll zu erklären.','میا دلیل های شغلی اش را مرتب می کند و تمرین می کند انگیزه اش را روشن و محترمانه توضیح بدهد.',4,42,43,2,'validated',JSON_OBJECT('databaseRevision','v9.1.1','staging',TRUE,'dependsOnSeries',81)) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),description_translation=VALUES(description_translation),status='validated',metadata=VALUES(metadata);

SET @chapter_id=LAST_INSERT_ID();

DELETE FROM lessons WHERE chapter_id=@chapter_id;

DELETE FROM words WHERE course_id=@course_id AND word_key LIKE 'de-fa-b1-082-%';

