(@course_id,'de-fa-b1-082-target-01','default','Weil ich mich beruflich weiterentwickeln möchte.','Weil ich mich beruflich weiterentwickeln möchte.','phrase','چون می خواهم از نظر شغلی پیشرفت کنم.',42,NULL,JSON_ARRAY('Weil ich heute nicht arbeiten möchte.','Obwohl die Stelle weit weg ist.'),NULL,82,1,82,82,JSON_OBJECT('explicitTarget',TRUE,'databaseRevision','v9.1.1')),
