INSERT INTO turns (lesson_id,character_id,turn_key,sort_order,role,text,translation,difficulty,speech_target,tokens,grammar_title,grammar_note,grammar_data) VALUES
(@l1,@sara_id,'B1-082-L01-T01',1,'character','Du hast deine Vorteile und Nachteile aufgeschrieben. Was steht ganz oben?','مزایا و معایبت را یادداشت کردی. بالای فهرست چه چیزی است؟',42,NULL,JSON_ARRAY(JSON_OBJECT('surface','Du','lemma','du','translation','تو','partOfSpeech','pronoun'),JSON_OBJECT('surface','hast','lemma','haben','translation','داشتن','partOfSpeech','verb'),JSON_OBJECT('surface','deine','lemma','dein','translation','مال تو / تو','partOfSpeech','determiner'),JSON_OBJECT('surface','Vorteile','lemma','Vorteil','translation','مزیت','partOfSpeech','noun'),JSON_OBJECT('surface','und','lemma','und','translation','و','partOfSpeech','conjunction'),JSON_OBJECT('surface','Nachteile','lemma','Nachteil','translation','عیب / نکته منفی','partOfSpeech','noun'),JSON_OBJECT('surface','aufgeschrieben','lemma','aufschreiben','translation','یادداشت کردن','partOfSpeech','verb','suffix','.','form','Partizip II'),JSON_OBJECT('surface','Was','lemma','was','translation','چی / چه','partOfSpeech','pronoun'),JSON_OBJECT('surface','steht','lemma','stehen','translation','قرار داشتن / ایستادن','partOfSpeech','verb'),JSON_OBJECT('surface','ganz','lemma','ganz','translation','کاملا / خیلی','partOfSpeech','adverb'),JSON_OBJECT('surface','oben','lemma','oben','translation','بالا / طبقه بالا','partOfSpeech','adverb','suffix','?')),NULL,NULL,NULL),
(@l1,@mia_id,'B1-082-L01-T02',2,'learner','Die neue Stelle steht ganz oben.','موقعیت شغلی جدید بالای فهرست است.',42,'Die neue Stelle steht ganz oben.',JSON_ARRAY(JSON_OBJECT('surface','Die','lemma','der','translation','حرف تعریف','partOfSpeech','article'),JSON_OBJECT('surface','neue','lemma','neu','translation','جدید / تازه','partOfSpeech','adjective'),JSON_OBJECT('surface','Stelle','lemma','Stelle','translation','موقعیت شغلی','partOfSpeech','noun'),JSON_OBJECT('surface','steht','lemma','stehen','translation','قرار داشتن / ایستادن','partOfSpeech','verb'),JSON_OBJECT('surface','ganz','lemma','ganz','translation','کاملا / خیلی','partOfSpeech','adverb'),JSON_OBJECT('surface','oben','lemma','oben','translation','بالا / طبقه بالا','partOfSpeech','adverb','suffix','.')),NULL,NULL,NULL),
(@l1,@sara_id,'B1-082-L01-T03',3,'character','Warum willst du die Stelle annehmen?','چرا می خواهی این موقعیت را قبول کنی؟',42,NULL,JSON_ARRAY(JSON_OBJECT('surface','Warum','lemma','warum','translation','چرا','partOfSpeech','adverb'),JSON_OBJECT('surface','willst','lemma','wollen','translation','خواستن','partOfSpeech','verb'),JSON_OBJECT('surface','du','lemma','du','translation','تو','partOfSpeech','pronoun'),JSON_OBJECT('surface','die','lemma','der','translation','حرف تعریف','partOfSpeech','article'),JSON_OBJECT('surface','Stelle','lemma','Stelle','translation','موقعیت شغلی','partOfSpeech','noun'),JSON_OBJECT('surface','annehmen','lemma','annehmen','translation','پذیرفتن / قبول کردن','partOfSpeech','verb','suffix','?')),NULL,NULL,NULL),
(@l1,@mia_id,'B1-082-L01-T04',4,'learner','Weil ich mich beruflich weiterentwickeln möchte.','چون می خواهم از نظر شغلی پیشرفت کنم.',42,'Weil ich mich beruflich weiterentwickeln möchte.',JSON_ARRAY(JSON_OBJECT('surface','Weil','lemma','weil','translation','چون / زیرا','partOfSpeech','conjunction'),JSON_OBJECT('surface','ich','lemma','ich','translation','من','partOfSpeech','pronoun'),JSON_OBJECT('surface','mich','lemma','ich','translation','من','partOfSpeech','pronoun'),JSON_OBJECT('surface','beruflich','lemma','beruflich','translation','از نظر شغلی','partOfSpeech','adverb'),JSON_OBJECT('surface','weiterentwickeln','lemma','sich weiterentwickeln','translation','پیشرفت کردن / رشد کردن','partOfSpeech','verb'),JSON_OBJECT('surface','möchte','lemma','möchten','translation','خواستن / مایل بودن','partOfSpeech','verb','suffix','.')),'Warum? – Weil ...','Eine warum-Frage kann mit einem weil-Satz beantwortet werden.',JSON_OBJECT('focus','reason')),
(@l1,@sara_id,'B1-082-L01-T05',5,'character','Was bedeutet das für dich?','این برای تو یعنی چه؟',42,NULL,JSON_ARRAY(JSON_OBJECT('surface','Was','lemma','was','translation','چی / چه','partOfSpeech','pronoun'),JSON_OBJECT('surface','bedeutet','lemma','bedeuten','translation','معنی دادن','partOfSpeech','verb'),JSON_OBJECT('surface','das','lemma','das','translation','این / آن','partOfSpeech','pronoun'),JSON_OBJECT('surface','für','lemma','für','translation','برای / به نفع','partOfSpeech','preposition'),JSON_OBJECT('surface','dich','lemma','du','translation','تو','partOfSpeech','pronoun','suffix','?')),NULL,NULL,NULL),
